-- Trigger V2 prompt §17.6 #3
CREATE OR REPLACE FUNCTION admina_rh.generate_document_reminder() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.date_expiration IS NOT NULL AND NEW.date_expiration <= NOW() + INTERVAL '15 days' THEN
    INSERT INTO admina_rh.d02_reminders (tenant_id, employee_id, type_rappel, description, date_echeance, statut, action_requise)
    VALUES (NEW.tenant_id, NEW.employee_id, 'expiration_document',
            'Renouvellement document ' || NEW.type_document || ' (numero ' || NEW.numero_document || ')',
            NEW.date_expiration, 'en_attente',
            CASE WHEN NEW.date_expiration < NOW() THEN 'URGENT: document expire'
                 ELSE 'Lancer procedure renouvellement' END)
    ON CONFLICT ON CONSTRAINT uq_reminder_doc DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_documents_reminder
  AFTER INSERT OR UPDATE ON admina_rh.d02_employee_documents
  FOR EACH ROW EXECUTE FUNCTION admina_rh.generate_document_reminder();

-- Trigger #4 : bascule statut auto
CREATE OR REPLACE FUNCTION admina_rh.update_document_status() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.date_expiration IS NOT NULL THEN
    IF NEW.date_expiration < NOW() THEN NEW.statut := 'Expire';
    ELSIF NEW.date_expiration <= NOW() + INTERVAL '30 days' THEN NEW.statut := 'A_renouveler';
    ELSE NEW.statut := 'Valide'; END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_document_status
  BEFORE INSERT OR UPDATE ON admina_rh.d02_employee_documents
  FOR EACH ROW EXECUTE FUNCTION admina_rh.update_document_status();

-- Trigger V2 prompt §17.6 #1
CREATE OR REPLACE FUNCTION admina_rh.update_contract_status() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.date_fin IS NOT NULL THEN
    IF NEW.date_fin < NOW() THEN NEW.statut := 'Echu';
    ELSIF NEW.date_fin <= NOW() + INTERVAL '30 days' THEN
      -- declencher rappel de renouvellement (seulement pour CDD/Stage)
      IF NEW.type_contrat IN ('CDD','Stage','Interim','Apprentissage') THEN
        INSERT INTO admina_rh.d02_reminders (tenant_id, employee_id, type_rappel, description, date_echeance, statut, action_requise)
        VALUES (NEW.tenant_id, NEW.employee_id, 'renouvellement_contrat',
                'Renouvellement contrat ' || NEW.contract_number,
                NEW.date_fin, 'en_attente',
                'Decider renouvellement ou fin contrat')
        ON CONFLICT ON CONSTRAINT uq_reminder_contract DO NOTHING;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_contracts_status
  BEFORE INSERT OR UPDATE ON admina_rh.d02_contracts
  FOR EACH ROW EXECUTE FUNCTION admina_rh.update_contract_status();

-- Trigger d'agregation hebdo -> mensuel
CREATE OR REPLACE FUNCTION admina_rh.aggregate_attendance_to_planning() RETURNS TRIGGER AS $$
DECLARE
  v_mois VARCHAR(20);
  v_annee INT;
  v_emp UUID;
BEGIN
  v_emp := NEW.employee_id;
  v_annee := EXTRACT(YEAR FROM to_date(split_part(NEW.semaine,'-',2)||'-W'||trim(leading 'S' from split_part(NEW.semaine,'-',1)), 'IYYY-IW'));
  v_mois := to_char(to_date(split_part(NEW.semaine,'-',2)||'-W'||trim(leading 'S' from split_part(NEW.semaine,'-',1)), 'IYYY-IW'), 'YYYY-MM');

  INSERT INTO admina_rh.d02_monthly_planning (tenant_id, employee_id, plan_number, mois, jours_ouvrables, jours_presents, jours_absents, retards_minutes, heures_supp, taux_presence, statut)
  SELECT $1, v_emp, 'PL-'||v_mois||'-'||substring(v_emp::text,1,8),
         v_mois,
         SUM(jours_ouvrables_hebdo),
         SUM(jours_presents),
         SUM(jours_absents),
         SUM(retards_minutes),
         SUM(heures_supp),
         ROUND(SUM(jours_presents)::numeric / NULLIF(SUM(jours_ouvrables_hebdo),0) * 100, 2),
         'brouillon'
  FROM (... weekly aggregates ...)
  ON CONFLICT (employee_id, mois) DO UPDATE SET
    jours_presents = EXCLUDED.jours_presents,
    jours_absents = EXCLUDED.jours_absents,
    retards_minutes = EXCLUDED.retards_minutes,
    heures_supp = EXCLUDED.heures_supp,
    taux_presence = EXCLUDED.taux_presence,
    updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_attendance_to_planning
  AFTER UPDATE OF statut ON admina_rh.d02_attendance_records
  FOR EACH ROW WHEN (NEW.statut = 'valide')
  EXECUTE FUNCTION admina_rh.aggregate_attendance_to_planning();

-- Les HS validees sont incluses automatiquement dans la generation de paie (cf. IC-D2-05)
-- Regle imperative : seules les HS 'validees' peuvent etre integrees en paie (cf. V2 prompt ECRAN 13 §4)

-- Trigger : apres paiement de la fiche de paie, marquer les HS correspondantes comme 'payee'
CREATE OR REPLACE FUNCTION admina_rh.mark_overtime_paid() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.statut = 'payee' AND (OLD.statut IS NULL OR OLD.statut != 'payee') THEN
    UPDATE admina_rh.d02_overtime_hours
    SET statut = 'payee', updated_at = NOW()
    WHERE employee_id = NEW.employee_id
      AND tenant_id = NEW.tenant_id
      AND statut = 'validee'
      AND LEFT(semaine, 7) = LEFT(NEW.mois, 7);
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_payslip_paid_mark_overtime
  AFTER UPDATE OF statut ON admina_rh.d02_pay_slips
  FOR EACH ROW WHEN (NEW.statut = 'payee')
  EXECUTE FUNCTION admina_rh.mark_overtime_paid();

CREATE OR REPLACE FUNCTION admina_rh.auto_create_medical_visit_on_absence() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.statut = 'justifiee' AND COALESCE(NEW.duree_jours, 0) > 3 THEN
    INSERT INTO admina_rh.d02_medical_visits (tenant_id, employee_id, type_visite, medecin_structure, date_visite, date_prochaine_visite, resultat, aptitude, restrictions, cout, prise_en_charge, observations)
    VALUES (
      NEW.tenant_id, NEW.employee_id, 'reprise',
      'A planifier',
      COALESCE(NEW.date_fin, NOW()::date) + INTERVAL '1 day',
      NULL, -- date prochaine visite a definir par le medecin
      'En attente',
      'apte', -- valeur par defaut, sera mise a jour par le medecin
      '', 0, 'Employeur',
      'Visite de reprise auto-generee suite absence ' || NEW.type_absence || ' de ' || NEW.duree_jours || ' jours'
    )
    ON CONFLICT ON CONSTRAINT uq_medical_visit_reprise DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_absence_create_medical_visit
  AFTER UPDATE OF statut ON admina_rh.d02_absences
  FOR EACH ROW WHEN (NEW.statut = 'justifiee' AND COALESCE(NEW.duree_jours,0) > 3)
  EXECUTE FUNCTION admina_rh.auto_create_medical_visit_on_absence();
